 new_normalized as(select i.*,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(i.category),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as category_key,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(coalesce(c.name_aliases->>i.name,i.name)),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as name_key,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(i.variety),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as variety_key from incoming i cross join config c ),
 existing_normalized as(select p.*,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(p.category),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as category_key,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(coalesce(c.name_aliases->>p.name,p.name)),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as name_key,regexp_replace(normalize(regexp_replace(replace(replace(replace(replace(lower(p.variety),'ä','ae'),'ö','oe'),'ü','ue'),'ß','ss'),'\([^)]*\)|\mf1\M','','g'),NFKD),'[^a-z0-9]','','g') as variety_key from public.rg_plants p cross join config c where p.family_id=target_family and p.is_catalog),
 inserted as(
 insert into public.rg_plants(family_id,name,variety,category,location,spacing,sowing,harvest,care,months,favorite,source,version,created_by,legacy_data,schedule,photo_path,is_catalog)
 select target_family,n.name,n.variety,n.category,'','','','',
 'Sortenname in der RHS-Referenzliste belegt. Standort, Pflanzabstand und Kulturzeiten sind für deinen Garten noch nicht geprüft; bitte örtliche Bedingungen und die konkrete Pflanzen- oder Saatgutangabe berücksichtigen. Quelle: https://www.rhs.org.uk/plants/pdfs/agm-lists/agm-fruit-and-vegetables#page='||n.page::text,
 '{}'::integer[],false,'seed',1,null,
 jsonb_build_object('catalog_import','catalog-expansion-20261101','source_url','https://www.rhs.org.uk/plants/pdfs/agm-lists/agm-fruit-and-vegetables#page='||n.page::text,'evidence',jsonb_build_object('publisher','Royal Horticultural Society','document','RHS Recommended: Award of Garden Merit – Fruit, vegetables and herbs','page',n.page,'listed_as',n.listed_as,'verified_on','2026-11-01','scope','Cultivar identity only; cultivation details unverified')),
 '{}'::jsonb,null,true
 from new_normalized n cross join config c
 where not exists(select 1 from existing_normalized e where e.category_key=n.category_key and e.name_key=n.name_key and coalesce(c.variety_aliases->>e.variety_key,e.variety_key)=coalesce(c.variety_aliases->>n.variety_key,n.variety_key))
 returning id)select count(*) into inserted_count from inserted;
 if inserted_count>200 then raise exception 'Unexpected import size';end if;
end $import$;
commit;
select count(*) as expansion_rows,count(*)filter(where category='Obst')as fruit_rows,count(*)filter(where category='Gemüse')as vegetable_rows
 from public.rg_plants where is_catalog and legacy_data->>'catalog_import'='catalog-expansion-20261101';
